SELECT id, country, rating, city, supplier_name, LAST_VALUE(city) OVER (PARTITION BY country ORDER BY rating DESC, id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS last_city, LAST_VALUE(supplier_name) OVER (PARTITION BY city ORDER BY rating DESC, id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS last_supplier_name FROM suppliers WHERE LENGTH(supplier_name) > 9;
